package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.net.*;import android.net.wifi.WifiManager;import android.provider.Settings;import android.widget.*;import android.view.*;import org.json.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
/** Device discovery and acknowledged AVTransport controls; renderer/video compatibility is never assumed. */
final class DlnaCastDialog {
 final ScrapedMainActivity a;final JSONObject source;final String title;final int owner;final LinearLayout list,controls;final TextView status;final AlertDialog dialog;final Button refresh;final ExecutorService worker=Executors.newSingleThreadExecutor();final ArrayList<Button> controlButtons=new ArrayList<>();volatile boolean closed;boolean busy;volatile DlnaClient.Scan scan;DlnaClient.Device selected;
 static void open(ScrapedMainActivity a,JSONObject source,String title){new DlnaCastDialog(a,source,title);}
 DlnaCastDialog(ScrapedMainActivity a,JSONObject source,String title){this.a=a;this.source=source;this.title=title;owner=a.epoch;LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(a.dp(16),a.dp(4),a.dp(16),a.dp(8));TextView note=a.text("手机与电视/盒子需在同一 Wi‑Fi，电视需开启 DLNA 媒体接收。支持的格式取决于电视。",13,a.muted());root.addView(note);status=a.text("准备搜索设备…",14,a.ink());root.addView(status);refresh=a.button("重新搜索设备",()->search());root.addView(refresh);ScrollView scroll=new ScrollView(a);list=new LinearLayout(a);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(180)));controls=new LinearLayout(a);controls.setOrientation(1);controls.setVisibility(View.GONE);root.addView(controls);
  LinearLayout transport=new LinearLayout(a);for(String[] c:new String[][]{{"播放","Play"},{"暂停","Pause"},{"停止","Stop"}}){Button b=a.button(c[0],()->control(c[1]));controlButtons.add(b);transport.addView(b,new LinearLayout.LayoutParams(0,-2,1));}controls.addView(transport);Button state=a.button("刷新电视播放状态",()->control("State"));controlButtons.add(state);controls.addView(state);
  dialog=new AlertDialog.Builder(a).setTitle("局域网投屏 · DLNA").setView(root).setNegativeButton("关闭面板",null).setNeutralButton("Wi‑Fi 设置",(d,n)->a.startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS))).create();dialog.setOwnerActivity(a);dialog.setOnDismissListener(d->{closed=true;DlnaClient.Scan current=scan;if(current!=null)current.close();worker.shutdownNow();});dialog.show();search();
 }
 boolean valid(){return !closed&&!a.isFinishing()&&!a.isDestroyed()&&a.epoch==owner;}
 void busy(boolean value){busy=value;refresh.setEnabled(!value);for(Button b:controlButtons)b.setEnabled(!value);for(int i=0;i<list.getChildCount();i++)list.getChildAt(i).setEnabled(!value);}
 InetAddress wifiAddress()throws Exception{ConnectivityManager cm=(ConnectivityManager)a.getSystemService(Context.CONNECTIVITY_SERVICE);if(cm!=null)for(Network network:cm.getAllNetworks()){NetworkCapabilities c=cm.getNetworkCapabilities(network);if(c==null||!(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)))continue;LinkProperties p=cm.getLinkProperties(network);if(p!=null)for(LinkAddress address:p.getLinkAddresses()){InetAddress ip=address.getAddress();if(ip instanceof Inet4Address&&!ip.isLoopbackAddress())return ip;}}throw new Exception("请连接与电视相同的 Wi‑Fi 后重新搜索");}
 void search(){if(busy||!valid())return;busy(true);selected=null;controls.setVisibility(View.GONE);list.removeAllViews();status.setText("正在搜索局域网设备，约需 8 秒…");scan=new DlnaClient.Scan();final DlnaClient.Scan task=scan;worker.execute(()->{WifiManager.MulticastLock lock=null;List<DlnaClient.Device> devices=null;String failure="";try{InetAddress address=wifiAddress();WifiManager wifi=(WifiManager)a.getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wifi!=null){lock=wifi.createMulticastLock("mediapocket-dlna-discovery");lock.setReferenceCounted(false);lock.acquire();}devices=task.find(address,4000);}catch(Exception e){failure=LinkProbe.reason(e);}finally{task.close();if(lock!=null)try{if(lock.isHeld())lock.release();}catch(RuntimeException ignored){}}final List<DlnaClient.Device> result=devices;final String reason=failure;a.runOnUiThread(()->{if(!valid())return;busy(false);if(result==null){status.setText("设备搜索失败 · "+reason);return;}if(result.isEmpty()){status.setText("未发现 DLNA 设备。请检查电视接收功能、同一 Wi‑Fi，以及路由器是否开启了设备隔离。");return;}status.setText("发现 "+result.size()+" 台设备，选择一台发送当前片源");for(DlnaClient.Device device:result){Button pick=a.button(device.name+"\n"+device.control.getHost(),()->send(device));list.addView(pick);}});});}
 void send(DlnaClient.Device device){if(busy||!valid())return;busy(true);selected=device;status.setText("正在向 "+device.name+" 发送片源…");worker.execute(()->{String report;boolean sent=false;try{if(!valid())return;DlnaClient.action(device,"SetAVTransportURI",DlnaClient.arguments("CurrentURI",source.optString("url"),"CurrentURIMetaData",DlnaClient.didl(source.optString("url"),title)));if(!valid()||Thread.currentThread().isInterrupted())return;DlnaClient.control(device,"Play");sent=true;try{report=stateText(DlnaClient.state(device));}catch(Exception e){report="电视已接受播放指令，暂未取得播放状态";}}catch(Exception e){report="投屏失败 · "+LinkProbe.reason(e);}final String message=report;final boolean acknowledged=sent;a.runOnUiThread(()->{if(!valid())return;busy(false);status.setText(device.name+"\n"+message);controls.setVisibility(acknowledged?View.VISIBLE:View.GONE);});});}
 static String stateText(String state){switch(state){case "PLAYING":return "电视报告：播放中";case "PAUSED_PLAYBACK":return "电视报告：已暂停";case "STOPPED":return "电视报告：已停止；若未出画面，请尝试其他片源或格式";case "TRANSITIONING":return "电视报告：正在准备播放";case "NO_MEDIA_PRESENT":return "电视报告：未载入媒体";default:return "电视返回状态："+(state.isEmpty()?"未知":state);}}
 void control(String command){if(busy||!valid()||selected==null)return;busy(true);DlnaClient.Device device=selected;worker.execute(()->{String message;try{if(!valid())return;if(!command.equals("State"))DlnaClient.control(device,command);try{message=stateText(DlnaClient.state(device));}catch(Exception e){message=command.equals("State")?"读取状态失败 · "+LinkProbe.reason(e):"电视已接受"+(command.equals("Pause")?"暂停":command.equals("Stop")?"停止":"播放")+"指令，暂未取得状态";}}catch(Exception e){message="操作失败 · "+LinkProbe.reason(e);}final String result=message;a.runOnUiThread(()->{if(!valid())return;busy(false);status.setText(device.name+"\n"+result);});});}
}
